/* anti-design-live-nuxt-plugin */
const liveSrc = 'http://localhost:8412/live.js?token=t';
const liveSelector = 'script[data-anti-design-live-nuxt]';

export default defineNuxtPlugin(() => {
  if (!import.meta.dev || typeof document === 'undefined') return;

  const expectedSrc = new URL(liveSrc, window.location.href).href;
  let script = document.querySelector<HTMLScriptElement>(liveSelector);
  if (script?.src === expectedSrc) return;
  script?.remove();

  script = document.createElement('script');
  script.src = liveSrc;
  script.async = true;
  script.dataset.antiDesignLiveNuxt = '';
  document.head.appendChild(script);

  import.meta.hot?.dispose(() => {
    if (script?.isConnected) script.remove();
  });
});
/* /anti-design-live-nuxt-plugin */
